{
  "propositions": [
    {
      "id": "P1",
      "proposition": "Physical activity used to satisfy Section 49-6-1021(a)(1) must include unstructured outdoor play unless weather conditions negatively impact reasonable execution of physical activity outside.",
      "importance": "core",
      "section": "SECTION 1",
      "source_quote": "(A) Must include unstructured play outside, unless weather conditions\n\n negatively impact reasonable execution of physical activity outside;"
    },
    {
      "id": "P2",
      "proposition": "Time during which a student is permitted to use an electronic device does not count as physical activity satisfying Section 49-6-1021(a)(1).",
      "importance": "core",
      "section": "SECTION 1",
      "source_quote": "(i) Time during which a student is permitted to use an electronic\n\n device;"
    },
    {
      "id": "P3",
      "proposition": "Time a student spends in a physical education class does not count as physical activity satisfying Section 49-6-1021(a)(1).",
      "importance": "core",
      "section": "SECTION 1",
      "source_quote": "(ii) Time spent by a student in a physical education class."
    },
    {
      "id": "P4",
      "proposition": "A student may be denied participation in physical activity, and a teacher or administrator may discipline the student by removing the student from or denying participation in any physical activity or physical activity period, for violating the school or school district's discipline policy or code of conduct, engaging in violent or threatening behavior, or engaging in other behavior that significantly disrupts or impairs other students' ability to participate in and receive the benefits of the required physical activity.",
      "importance": "core",
      "section": "SECTION 1",
      "source_quote": "(i) Remove a student from, or deny a student participation in, any\n\n physical activity or physical activity period for engaging in any conduct or\n\n behavior described in this subdivision (b)(3);"
    },
    {
      "id": "P5",
      "proposition": "A teacher or administrator may, as discipline, assign a student removed from or denied participation in physical activity under subdivision (b)(3) alternative lessons, assignments, or activities, including physical activities, to improve the student's conduct or behavior.",
      "importance": "core",
      "section": "SECTION 1",
      "source_quote": "alternative lessons, assignments, or activities, including\n\n physical activities, to improve the student's conduct or behavior."
    },
    {
      "id": "P6",
      "proposition": "The act takes effect upon becoming a law.",
      "importance": "supporting",
      "section": "SECTION 2",
      "source_quote": "This act takes effect upon becoming a law, the public welfare requiring it."
    }
  ]
}

